import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { getImageUrl } from '../services/api';
import { motion, AnimatePresence } from 'framer-motion';
import { Link } from 'react-router-dom';
import styles from './UserDashboard.module.css';

const UserDashboard = () => {
  const { user, setUser, notifications, clearNotifications } = useAuth();
  const [activeTab, setActiveTab] = useState('profile');
  const [purchases, setPurchases] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loans, setLoans] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [compareIds, setCompareIds] = useState([]);
  const [loading, setLoading] = useState(true);
  
  const [printingId, setPrintingId] = useState(null);
  const [showReviewModal, setShowReviewModal] = useState(false);
  const [activeReviewTd, setActiveReviewTd] = useState(null);
  const [hoverRating, setHoverRating] = useState(null);
  
  const [showViewModal, setShowViewModal] = useState(false);
  const [viewComment, setViewComment] = useState(null);
  
  const [profileForm, setProfileForm] = useState({
    full_name: user?.full_name || '',
    phone: user?.phone || '',
  });
  const [updateLoading, setUpdateLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // Для отзывов на тест-драйв
  const [reviewForm, setReviewForm] = useState({
    rating: 5,
    comment: ''
  });
  const [reviewError, setReviewError] = useState('');
  const [reviewSuccess, setReviewSuccess] = useState('');

  // Состояния для пагинации (по 4 элемента на страницу)
  const [purchasePage, setPurchasePage] = useState(1);
  const [testDrivePage, setTestDrivePage] = useState(1);
  const [loanPage, setLoanPage] = useState(1);
  const ITEMS_PER_PAGE = 4;

  useEffect(() => {
    if (user) {
      setProfileForm({
        full_name: user.full_name || '',
        phone: user.phone || '',
      });
    }
  }, [user]);

  const fetchDashboardData = useCallback(async () => {
    try {
      setLoading(true);
      
      const [purchasesRes, testDrivesRes, loansRes, favoritesRes] = await Promise.all([
        api.get('/purchases/my').catch(() => ({ data: [] })),
        api.get('/testdrives/my').catch(() => ({ data: [] })),
        api.get('/loans/my').catch(() => ({ data: [] })),
        api.get('/cars/favorites').catch(() => ({ data: [] }))
      ]);

      setPurchases(purchasesRes.data);
      setTestDrives(testDrivesRes.data);
      setLoans(loansRes.data);
      setFavorites(favoritesRes.data);

      // Загружаем список сравнения из localStorage (безопасные не-персональные ID авто)
      const storedCompare = localStorage.getItem('compareList');
      if (storedCompare) {
        setCompareIds(JSON.parse(storedCompare));
      }
    } catch (err) {
      console.error("Ошибка загрузки данных личного кабинета:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');
    setUpdateLoading(true);
    try {
      const res = await api.put('/auth/update-profile', profileForm);
      setUser(res.data.user);
      setSuccess('Профиль успешно обновлен!');
    } catch (err) {
      setError(err.response?.data?.detail || 'Ошибка при обновлении профиля');
    } finally {
      setUpdateLoading(false);
    }
  };

  const handlePrintReceipt = (purchase) => {
    setPrintingId(purchase.id);
    
    // Даем реакту время отрендерить состояние printingId, чтобы применились стили @media print
    setTimeout(() => {
      window.print();
      setPrintingId(null);
    }, 150);
  };

  const toggleFavorite = async (carId) => {
    try {
      await api.post(`/cars/${carId}/favorite`);
      setFavorites(prev => prev.filter(car => car.id !== carId));
    } catch (err) {
      console.error("Ошибка при удалении из избранного:", err);
    }
  };

  const removeFromCompare = (carId) => {
    const updated = compareIds.filter(id => id !== carId);
    setCompareIds(updated);
    localStorage.setItem('compareList', JSON.stringify(updated));
  };

  // Открытие модалки для создания отзыва
  const openReviewModal = (td) => {
    setActiveReviewTd(td);
    setReviewForm({ rating: 5, comment: '' });
    setReviewError('');
    setReviewSuccess('');
    setShowReviewModal(true);
  };

  const handleReviewSubmit = async (e) => {
    e.preventDefault();
    setReviewError('');
    setReviewSuccess('');
    try {
      await api.post('/testdrives/review', {
        test_drive_id: activeReviewTd.id,
        rating: reviewForm.rating,
        comment: reviewForm.comment
      });
      setReviewSuccess('Отзыв успешно отправлен! Спасибо за обратную связь.');
      
      // Спустя 2 секунды закрываем и обновляем данные
      setTimeout(() => {
        setShowReviewModal(false);
        setActiveReviewTd(null);
        fetchDashboardData();
      }, 2000);
    } catch (err) {
      setReviewError(err.response?.data?.detail || 'Не удалось отправить отзыв');
    }
  };

  // Функция для постраничного разбиения локальных массивов
  const paginate = (array, pageNumber) => {
    const startIndex = (pageNumber - 1) * ITEMS_PER_PAGE;
    return array.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  };

  const renderPaginationButtons = (totalItems, currentPage, setPage) => {
    const totalPages = Math.ceil(totalItems / ITEMS_PER_PAGE);
    if (totalPages <= 1) return null;

    return (
      <div className={styles.pagination}>
        {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
          <button
            key={page}
            className={`${styles.pageBtn} ${page === currentPage ? styles.activePage : ''}`}
            onClick={() => setPage(page)}
          >
            {page}
          </button>
        ))}
      </div>
    );
  };

  if (loading) {
    return <div className={styles.loading}>Загрузка данных личного кабинета...</div>;
  }

  return (
    <div className={styles.container}>
      <h2 className={styles.title}>Личный кабинет</h2>
      
      <div className={styles.tabs}>
        <button className={`${styles.tab} ${activeTab === 'profile' ? styles.active : ''}`} onClick={() => setActiveTab('profile')}>Профиль</button>
        <button className={`${styles.tab} ${activeTab === 'purchases' ? styles.active : ''}`} onClick={() => setActiveTab('purchases')}>Покупки ({purchases.length})</button>
        <button className={`${styles.tab} ${activeTab === 'testdrives' ? styles.active : ''}`} onClick={() => setActiveTab('testdrives')}>Тест-драйвы ({testDrives.length})</button>
        <button className={`${styles.tab} ${activeTab === 'loans' ? styles.active : ''}`} onClick={() => setActiveTab('loans')}>Кредиты ({loans.length})</button>
        <button className={`${styles.tab} ${activeTab === 'favorites' ? styles.active : ''}`} onClick={() => setActiveTab('favorites')}>Избранное ({favorites.length})</button>
        <button className={`${styles.tab} ${activeTab === 'notifications' ? styles.active : ''}`} onClick={() => setActiveTab('notifications')}>Уведомления ({notifications.length})</button>
      </div>

      <div className={styles.tabContent}>
        {/* ВКЛАДКА: ПРОФИЛЬ */}
        {activeTab === 'profile' && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className={styles.profileSection}>
            <div className={styles.card}>
              <h3>Личные данные</h3>
              <p style={{ marginBottom: '1.5rem', opacity: 0.7 }}>Вы можете обновить свои контактные данные, которые будут автоматически подставляться в заявки.</p>
              
              <form onSubmit={handleProfileSubmit} className={styles.form}>
                <div className={styles.formGroup}>
                  <label>Электронная почта (логин)</label>
                  <input type="email" value={user?.email || ''} disabled className={styles.disabledInput} />
                  <small style={{ color: 'gray', marginTop: '0.2rem', display: 'block' }}>Изменение email не поддерживается в целях безопасности.</small>
                </div>
                
                <div className={styles.formGroup}>
                  <label>ФИО</label>
                  <input 
                    type="text" 
                    value={profileForm.full_name} 
                    onChange={e => setProfileForm({ ...profileForm, full_name: e.target.value })} 
                    placeholder="Введите ваше полное имя"
                    required
                  />
                </div>
                
                <div className={styles.formGroup}>
                  <label>Телефон</label>
                  <input 
                    type="text" 
                    value={profileForm.phone} 
                    onChange={e => setProfileForm({ ...profileForm, phone: e.target.value })} 
                    placeholder="+7 (999) 123-4567"
                    required
                  />
                </div>

                {error && <div className={styles.errorMsg}>{error}</div>}
                {success && <div className={styles.successMsg}>{success}</div>}
                
                <button type="submit" className={styles.submitBtn} disabled={updateLoading}>
                  {updateLoading ? 'Сохранение...' : 'Сохранить изменения'}
                </button>
              </form>
            </div>
          </motion.div>
        )}

        {/* ВКЛАДКА: ПОКУПКИ */}
        {activeTab === 'purchases' && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            {purchases.length === 0 ? (
              <div className={styles.emptyState}>
                <p>У вас пока нет оформленных покупок автомобилей.</p>
                <Link to="/catalog" className={styles.submitBtn} style={{ display: 'inline-block', marginTop: '1rem', textDecoration: 'none' }}>Перейти в каталог</Link>
              </div>
            ) : (
              <>
                <div className={styles.listContainer}>
                  {paginate(purchases, purchasePage).map(p => {
                    const isCurrentPrinting = printingId === p.id;
                    return (
                      <div 
                        key={p.id} 
                        className={`${styles.listItemCard} ${isCurrentPrinting ? styles.printableReceiptActive : ''}`}
                        id={`receipt-card-${p.id}`}
                      >
                        <div className={styles.receiptPrintHeader}>
                          <h2>LUXURY DEALER AUTOMOTIVE</h2>
                          <p>Официальный дилер премиальных автомобилей</p>
                          <hr />
                        </div>

                        <div className={styles.listItemMain}>
                          <img src={getImageUrl(p.car_image_url || p.car?.image_url)} alt={`${p.car_brand} ${p.car_model}`} className={styles.listItemImg} />
                          <div className={styles.listItemInfo}>
                            <h4>{p.car_brand} {p.car_model} ({p.car_year})</h4>
                            <p className={styles.priceText}>Стоимость: {p.price?.toLocaleString()} ₽</p>
                            <p><strong>Дата сделки:</strong> {new Date(p.created_at).toLocaleDateString()} в {new Date(p.created_at).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</p>
                            <p><strong>ID Операции:</strong> #LD-PURCHASE-{p.id}</p>
                            <p><strong>Покупатель:</strong> {user?.full_name || 'Не указано'}</p>
                            <p><strong>Контакты:</strong> {user?.phone || user?.email}</p>
                            <span className={`${styles.statusBadge} ${styles.statusApproved}`}>Сделка завершена</span>
                          </div>
                        </div>

                        <div className={styles.listItemActions}>
                          <button 
                            type="button"
                            className={styles.printBtn} 
                            onClick={() => handlePrintReceipt(p)}
                          >
                            🖨️ Печать чека
                          </button>
                        </div>

                        <div className={styles.receiptPrintFooter}>
                          <hr />
                          <p>Благодарим вас за покупку в нашем автосалоне!</p>
                          <p>Данный документ сформирован в личном кабинете клиента и подтверждает факт проведения транзакции.</p>
                        </div>
                      </div>
                    );
                  })}
                </div>
                {renderPaginationButtons(purchases.length, purchasePage, setPurchasePage)}
              </>
            )}
          </motion.div>
        )}

        {/* ВКЛАДКА: ТЕСТ-ДРАЙВЫ */}
        {activeTab === 'testdrives' && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            {testDrives.length === 0 ? (
              <div className={styles.emptyState}>
                <p>Вы еще не записывались на тест-драйв.</p>
                <Link to="/catalog" className={styles.submitBtn} style={{ display: 'inline-block', marginTop: '1rem', textDecoration: 'none' }}>Выбрать авто</Link>
              </div>
            ) : (
              <>
                <div className={styles.listContainer}>
                  {paginate(testDrives, testDrivePage).map(td => (
                    <div key={td.id} className={styles.listItemCard}>
                      <div className={styles.listItemMain}>
                        <img src={getImageUrl(td.car?.image_url)} alt={`${td.car?.brand} ${td.car?.model}`} className={styles.listItemImg} />
                        <div className={styles.listItemInfo}>
                          <h4>{td.car?.brand} {td.car?.model} ({td.car?.year})</h4>
                          <p><strong>Желаемая дата:</strong> {new Date(td.preferred_date).toLocaleDateString()}</p>
                          <p><strong>Контактный телефон:</strong> {td.phone}</p>
                          {td.message && <p><strong>Ваш комментарий:</strong> "{td.message}"</p>}
                          
                          <div style={{ marginTop: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                            <strong>Статус:</strong> 
                            <span className={`${styles.statusBadge} ${styles[td.status] || styles.pending}`}>
                              {td.status === 'pending' && 'На рассмотрении'}
                              {td.status === 'approved' && 'Одобрено'}
                              {td.status === 'rejected' && 'Отклонено'}
                            </span>
                          </div>

                          {td.admin_comment && (
                            <div className={styles.commentContainer}>
                              <strong>Ответ менеджера:</strong>
                              <button 
                                className={styles.commentIconBtn}
                                onClick={() => {
                                  setViewComment({
                                    title: "Ответ автосалона по тест-драйву",
                                    subtitle: `${td.car?.brand} ${td.car?.model}`,
                                    comment: td.admin_comment
                                  });
                                  setShowViewModal(true);
                                }}
                                title="Посмотреть полностью"
                              >
                                💬 Читать ответ
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                      
                      <div className={styles.listItemActions}>
                        {td.status === 'approved' && (
                          <button 
                            type="button" 
                            className={styles.reviewBtn} 
                            onClick={() => openReviewModal(td)}
                          >
                            ⭐ Оставить отзыв
                          </button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
                {renderPaginationButtons(testDrives.length, testDrivePage, setTestDrivePage)}
              </>
            )}
          </motion.div>
        )}

        {/* ВКЛАДКА: КРЕДИТЫ */}
        {activeTab === 'loans' && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            {loans.length === 0 ? (
              <div className={styles.emptyState}>
                <p>У вас нет активных или рассчитанных заявок на кредит.</p>
              </div>
            ) : (
              <>
                <div className={styles.listContainer}>
                  {paginate(loans, loanPage).map(loan => (
                    <div key={loan.id} className={styles.listItemCard}>
                      <div className={styles.listItemMain}>
                        <img src={getImageUrl(loan.car?.image_url)} alt={`${loan.car?.brand} ${loan.car?.model}`} className={styles.listItemImg} />
                        <div className={styles.listItemInfo}>
                          <h4>Кредит на {loan.car?.brand} {loan.car?.model}</h4>
                          <p><strong>Сумма кредита:</strong> {loan.amount?.toLocaleString()} ₽</p>
                          <p><strong>Срок:</strong> {loan.term_months} мес. ({Math.round(loan.term_months/12 * 10)/10} г.)</p>
                          <p><strong>Ставка:</strong> {loan.interest_rate}%</p>
                          <p className={styles.priceText}><strong>Ежемесячный платеж:</strong> {loan.monthly_payment?.toLocaleString()} ₽/мес.</p>
                          <p style={{ fontSize: '0.85rem', opacity: 0.8 }}>Всего к возврату: {loan.total_payment?.toLocaleString()} ₽ | Переплата: {loan.overpayment?.toLocaleString()} ₽</p>
                          
                          <div style={{ marginTop: '0.5rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                            <strong>Статус заявки:</strong> 
                            <span className={`${styles.statusBadge} ${styles[loan.status] || styles.calculated}`}>
                              {loan.status === 'calculated' && 'Черновик / Расчёт'}
                              {loan.status === 'pending' && 'На согласовании'}
                              {loan.status === 'approved' && 'Одобрен банком'}
                              {loan.status === 'rejected' && 'Отклонен банком'}
                            </span>
                          </div>

                          {loan.admin_comment && (
                            <div className={styles.commentContainer}>
                              <strong>Решение кредитного отдела:</strong>
                              <button 
                                className={styles.commentIconBtn}
                                onClick={() => {
                                  setViewComment({
                                    title: "Решение кредитного отдела автосалона",
                                    subtitle: `Параметры: ${loan.amount?.toLocaleString()} ₽ на ${loan.term_months} мес.`,
                                    comment: loan.admin_comment
                                  });
                                  setShowViewModal(true);
                                }}
                                title="Посмотреть подробности"
                              >
                                💬 Читать решение
                              </button>
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                {renderPaginationButtons(loans.length, loanPage, setLoanPage)}
              </>
            )}
          </motion.div>
        )}

        {/* ВКЛАДКА: ИЗБРАННОЕ */}
        {activeTab === 'favorites' && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            {favorites.length === 0 ? (
              <div className={styles.emptyState}>
                <p>В вашем списке избранного пока пусто.</p>
                <Link to="/catalog" className={styles.submitBtn} style={{ display: 'inline-block', marginTop: '1rem', textDecoration: 'none' }}>Смотреть машины</Link>
              </div>
            ) : (
              <div className={styles.cardsGrid}>
                {favorites.map(car => (
                  <div key={car.id} className={styles.card}>
                    <img src={getImageUrl(car.image_url)} alt={`${car.brand} ${car.model}`} className={styles.cardImg} />
                    <div className={styles.cardBody}>
                      <h4>{car.brand} {car.model}</h4>
                      <p className={styles.cardYear}>{car.year} г.в. | {car.engine_power || '340'} л.с. | {car.engine_volume || '3.0'}л</p>
                      <p className={styles.cardPrice}>{car.price?.toLocaleString()} ₽</p>
                      <div className={styles.cardButtons}>
                        <Link to={`/catalog/${car.id}`} className={styles.detailLink}>Подробнее</Link>
                        <button type="button" className={styles.removeFavBtn} onClick={() => toggleFavorite(car.id)} title="Убрать из избранного">❤️</button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </motion.div>
        )}

        {/* ВКЛАДКА: УВЕДОМЛЕНИЯ */}
        {activeTab === 'notifications' && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
            <div className={styles.card}>
              <div style={{ display: 'flex', justifyContent: 'between', alignItems: 'center', marginBottom: '1.5rem', width: '100%' }}>
                <h3>История уведомлений</h3>
                {notifications.length > 0 && (
                  <button type="button" className={styles.clearBtn} onClick={clearNotifications}>Очистить всё</button>
                )}
              </div>
              
              {notifications.length === 0 ? (
                <p style={{ opacity: 0.6, textAlign: 'center', padding: '2rem 0' }}>Новых системных уведомлений нет.</p>
              ) : (
                <div className={styles.notifList}>
                  {notifications.map(n => (
                    <div key={n.id} className={styles.notifItem}>
                      <span className={styles.notifTime}>{new Date(n.id).toLocaleTimeString()}</span>
                      <p className={styles.notifText}>{n.message}</p>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </motion.div>
        )}
      </div>

      {/* МОДАЛЬНОЕ ОКНО: ОТПРАВКА ОТЗЫВА ПО ТЕСТ-ДРАЙВУ */}
      <AnimatePresence>
        {showReviewModal && activeReviewTd && (
          <motion.div className={styles.modalOverlay} initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowReviewModal(false)}>
            <motion.div 
              className={styles.modal} 
              initial={{ scale: 0.9, opacity: 0 }} 
              animate={{ scale: 1, opacity: 1 }} 
              exit={{ scale: 0.9, opacity: 0 }}
              onClick={e => e.stopPropagation()}
            >
              <button className={styles.modalClose} onClick={() => setShowReviewModal(false)}>✕</button>
              <h3 className={styles.modalTitle}>Оставить отзыв о тест-драйве</h3>
              <p className={styles.modalSubtitle}>Поделитесь впечатлениями об автомобиле {activeReviewTd.car?.brand} {activeReviewTd.car?.model}</p>
              
              <form onSubmit={handleReviewSubmit} className={styles.form}>
                <div className={styles.formGroup} style={{ alignItems: 'center' }}>
                  <label style={{ marginBottom: '0.5rem' }}>Ваша оценка</label>
                  <div className={styles.starRating}>
                    {[1, 2, 3, 4, 5].map((star) => (
                      <span
                        key={star}
                        className={`${styles.star} ${(hoverRating || reviewForm.rating) >= star ? styles.starFilled : ''}`}
                        onClick={() => setReviewForm({ ...reviewForm, rating: star })}
                        onMouseEnter={() => setHoverRating(star)}
                        onMouseLeave={() => setHoverRating(null)}
                      >
                        ★
                      </span>
                    ))}
                  </div>
                </div>

                <div className={styles.formGroup}>
                  <label>Ваш комментарий / впечатления</label>
                  <textarea
                    rows="4"
                    value={reviewForm.comment}
                    onChange={e => setReviewForm({ ...reviewForm, comment: e.target.value })}
                    placeholder="Что понравилось, как вела себя машина на дороге, как отработал менеджер..."
                    required
                  ></textarea>
                </div>

                {reviewError && <div className={styles.errorMsg}>{reviewError}</div>}
                {reviewSuccess && <div className={styles.successMsg}>{reviewSuccess}</div>}

                <div className={styles.modalActions}>
                  <button type="button" className={styles.cancelBtn} onClick={() => setShowReviewModal(false)}>Отмена</button>
                  <button type="submit" className={styles.submitBtn} disabled={!!reviewSuccess}>Отправить отзыв</button>
                </div>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* МОДАЛЬНОЕ ОКНО ДЛЯ ПРОСМОТРА СИСТЕМНЫХ КОММЕНТАРИЕВ */}
      <AnimatePresence>
        {showViewModal && viewComment && (
          <motion.div 
            className={styles.modalOverlay}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={() => { setShowViewModal(false); setViewComment(null); }}
          >
            <motion.div 
              className={styles.modal}
              initial={{ scale: 0.95, opacity: 0, y: 20 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 20 }}
              transition={{ duration: 0.2 }}
              onClick={(e) => e.stopPropagation()}
            >
              <button className={styles.modalClose} onClick={() => { setShowViewModal(false); setViewComment(null); }}>✕</button>
              <h3 className={styles.modalTitle}>{viewComment.title}</h3>
              <p className={styles.modalSubtitle}>{viewComment.subtitle}</p>
              
              <div className={styles.modalField}>
                <div style={{ background: 'rgba(128, 128, 128, 0.08)', padding: '1.2rem', borderRadius: '14px', fontStyle: 'italic', lineHeight: '1.6', borderLeft: '4px solid var(--primary)', color: 'var(--text)', whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
                  {viewComment.comment}
                </div>
              </div>
              
              <div className={styles.modalActions}>
                <button 
                  type="button" 
                  className={styles.submitBtn} 
                  onClick={() => { setShowViewModal(false); setViewComment(null); }}
                >
                  Закрыть
                </button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export default UserDashboard;
